/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';
function setup(handoff) {
  const store = createDocumentStore({ a: 'A', b: 'B', c: 'C' });
  const shown = [];
  const nav = createWorkspace({ store, renderDocument: value => shown.push(value), onHandoff: handoff });
  return { store, shown, nav };
}
{
  const handoffs = [];
  const x = setup((snapshot) => handoffs.push(snapshot));
  x.nav.open('a'); x.nav.edit('edited'); x.nav.open('b');
  assert.deepEqual(handoffs, [{ id: 'a', text: 'edited' }]);
  assert.deepEqual(x.shown.at(-1), { id: 'b', text: 'B' });
  assert.equal(x.store.read('a'), 'edited');
  x.nav.dispose();
  assert.equal(handoffs.length, 1);
}
{
  let handoffs = 0;
  const x = setup((snapshot, nav) => { handoffs++; if (snapshot.id === 'a') nav.open('c'); });
  x.nav.open('a'); x.nav.open('b'); x.nav.edit('winner');
  assert.deepEqual(x.shown.at(-1), { id: 'c', text: 'C' });
  assert.equal(x.store.read('c'), 'winner');
  assert.equal(x.store.read('b'), 'B');
  assert.equal(handoffs, 1);
}
{
  const x = setup((snapshot, nav) => { if (snapshot.id === 'a') nav.close(); });
  x.nav.open('a'); x.nav.open('b');
  assert.equal(x.shown.at(-1), null);
}
console.log('navigation checks passed');
EOF"

